-- ============================================================
-- V10 (yashan) 合同管理增强 + 项目分工
--
-- 1) contract 表扩充"政府合同常见字段"：
--    合同类型 / 甲方 / 关键日期 / 合同状态 / 付款账户 / 验收标准 / 质保
--    说明：乙方沿用既有 vendor_name（供应商=承接单位），不再另设 party_b 以免字段冗余。
-- 2) 新增字典 CONTRACT_TYPE（合同类型）、CONTRACT_STATUS（合同状态）
-- 3) 新建 project_division 项目分工表（支持父子模块层级）
-- 4) 新增字典 DIVISION_STATUS（分工状态）
--
-- 约定（与既有迁移一致）：
--   * 主键 BIGINT GENERATED BY DEFAULT AS IDENTITY
--   * 字符列一律 VARCHAR(n CHAR)
--   * 索引在表外单独 CREATE INDEX
--   * 字典统一存 dict_item(dict_type, code, name, sort_no)；
--     配色不落库，在 frontend/src/config/tagDict.ts 里维护（见该文件 CONTRACT_TYPE_TAGS 等）
-- ============================================================

-- ── 1) 合同表扩充字段 ─────────────────────────────────────────
ALTER TABLE contract ADD (
    contract_type       VARCHAR(40 CHAR)   NULL,
    party_a             VARCHAR(128 CHAR)  NULL,
    sign_date           DATE               NULL,
    effective_date      DATE               NULL,
    start_date          DATE               NULL,
    end_date            DATE               NULL,
    contract_status     VARCHAR(40 CHAR)   NULL,
    payee_name          VARCHAR(128 CHAR)  NULL,
    payee_bank          VARCHAR(128 CHAR)  NULL,
    payee_account       VARCHAR(64 CHAR)   NULL,
    acceptance_standard VARCHAR(1000 CHAR) NULL,
    warranty_months     INT                NULL,
    warranty_amount     NUMBER(15,2)       NULL,
    settle_amount       NUMBER(15,2)       NULL
);

COMMENT ON COLUMN contract.contract_type       IS '合同类型(字典 CONTRACT_TYPE)：施工/第三方测评/方案评估/监理/设计/预算编制等';
COMMENT ON COLUMN contract.party_a             IS '甲方（建设单位/采购人）';
COMMENT ON COLUMN contract.sign_date           IS '签订日期';
COMMENT ON COLUMN contract.effective_date      IS '生效日期';
COMMENT ON COLUMN contract.start_date          IS '工期开始日期';
COMMENT ON COLUMN contract.end_date            IS '工期结束日期';
COMMENT ON COLUMN contract.contract_status     IS '合同状态(字典 CONTRACT_STATUS)';
COMMENT ON COLUMN contract.payee_name          IS '收款户名';
COMMENT ON COLUMN contract.payee_bank          IS '收款开户银行';
COMMENT ON COLUMN contract.payee_account       IS '收款银行账号';
COMMENT ON COLUMN contract.acceptance_standard IS '验收标准';
COMMENT ON COLUMN contract.warranty_months     IS '质保期（月）';
COMMENT ON COLUMN contract.warranty_amount     IS '质保金(元)';
COMMENT ON COLUMN contract.settle_amount       IS '结算金额(元)';

