-- ── 3) 项目分工表 ─────────────────────────────────────────────
-- 支持两级及以上：parent_id 为空是顶层模块，不为空是子模块。
-- 一份分工记录 = 一个"谁负责什么、什么时候做完、现在到哪一步"的条目。
CREATE TABLE project_division (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    project_id       BIGINT           NOT NULL,
    parent_id        BIGINT           NULL,
    name             VARCHAR(128 CHAR) NOT NULL,
    owner_side       VARCHAR(20 CHAR)  NULL,
    owner_name       VARCHAR(64 CHAR)  NULL,
    vendor_owner     VARCHAR(64 CHAR)  NULL,
    plan_dev_date    DATE             NULL,
    plan_test_date   DATE             NULL,
    plan_online_date DATE             NULL,
    progress         INT              NOT NULL DEFAULT 0,
    status           VARCHAR(20 CHAR)  NULL,
    remark           VARCHAR(500 CHAR) NULL,
    sort_no          INT              NOT NULL DEFAULT 0,
    create_time      TIMESTAMP        NULL,
    update_time      TIMESTAMP        NULL,
    deleted          TINYINT          NOT NULL DEFAULT 0,
    PRIMARY KEY (id)
);

COMMENT ON TABLE  project_division                  IS '项目分工（模块/子模块的负责方、负责人、计划时间与进度）';
COMMENT ON COLUMN project_division.id               IS '主键';
COMMENT ON COLUMN project_division.project_id       IS '所属项目（含子项目）';
COMMENT ON COLUMN project_division.parent_id        IS '父级分工 id（空=顶层模块）';
COMMENT ON COLUMN project_division.name             IS '模块/子模块名称';
COMMENT ON COLUMN project_division.owner_side       IS '负责方：OWNER 甲方 / VENDOR 乙方 / BOTH 双方';
COMMENT ON COLUMN project_division.owner_name       IS '甲方负责人';
COMMENT ON COLUMN project_division.vendor_owner     IS '乙方负责人';
COMMENT ON COLUMN project_division.plan_dev_date    IS '计划开发完成日期';
COMMENT ON COLUMN project_division.plan_test_date   IS '计划调试完成日期';
COMMENT ON COLUMN project_division.plan_online_date IS '计划上线日期';
COMMENT ON COLUMN project_division.progress         IS '当前进度（0-100）';
COMMENT ON COLUMN project_division.status           IS '状态(字典 DIVISION_STATUS)';
COMMENT ON COLUMN project_division.remark           IS '备注';
COMMENT ON COLUMN project_division.sort_no          IS '同级排序号';

CREATE INDEX idx_div_project ON project_division (project_id);
CREATE INDEX idx_div_parent  ON project_division (parent_id);

-- ── 4) 字典：分工状态 ─────────────────────────────────────────
INSERT INTO dict_item (dict_type, code, name, sort_no) VALUES ('DIVISION_STATUS', 'TODO',  '未开始', 1);
INSERT INTO dict_item (dict_type, code, name, sort_no) VALUES ('DIVISION_STATUS', 'DOING', '进行中', 2);
